        end = line.find(',', start)
        if end == -1:
            end = len(line)
        field = line[start:end]
        next_start = end + 1
    else:
        end = start
        while True:
            end = line.find('"', end + 1)
            if end == -1:
                raise ValueError("Unmatched quote in line")
            if end + 1 < len(line) and line[end + 1] == '"':
                end += 1
            else:
                break
        field = line[start + 1:end].replace('""', '"')
        next_start = end + 2

    return field, next_start
